import React from "react";
import { Link, useNavigate } from "react-router-dom";

const Navbar = () => {
  const navigate = useNavigate();

  const handleLogout = () => {
    localStorage.removeItem("user"); // Kullanıcı oturum bilgisini temizle
    navigate("/"); // Giriş sayfasına yönlendir
  };

  return (
    <nav className="navbar">
      <ul>
        <li><Link to="/employees">Çalışan Listesi</Link></li>
        <li><Link to="/leave-request">Geçmiş İzin Talepleri</Link></li>
        <li><Link to="/add-employee">Çalışan Ekle</Link></li>
        <li><Link to="/new-leave-request">İzin Talep Et</Link></li>
      </ul>
      <button className="logout-button" onClick={handleLogout}>Çıkış Yap</button>
    </nav>
  );
};

export default Navbar;
